fn hook(mods:&[horizon_client::mod_content::ContentMod])->core::ops::ControlFlow<()>{let types=horizon_client::mod_content::entity_types(mods);let _=horizon_client::projectiles::register_thrown_types(types.iter().filter(|t|t.template!="minecraft:allay").filter_map(|t|t.item.clone().map(|item|(t.id.clone(),item,t.damage))));core::ops::ControlFlow::Break(())}
